@dataclass(kw_only=True, slots=True)
class ProjectAccessChange(_Model):
    """The result of `project.share` and `project.access.revoke`; a retry with the
    same idempotency key gets the same one (`replayed`).
    Attributes:
        changed: Whether anything changed (sharing the same role again, or revoking what is not there, does not).
        event_seq: The `project.access` event, when something changed.
        grant: The grant now; absent after a revoke.
    """
    user_id: str
    changed: bool
    event_seq: str | None | Unset = UNSET
    grant: ProjectGrant | None | Unset = UNSET
    replayed: bool = False

    def to_json(self) -> dict[str, Any]:
        out: dict[str, Any] = {}
        out["userId"] = self.user_id
        out["changed"] = self.changed
        if self.event_seq is not UNSET:
            out["eventSeq"] = self.event_seq
        if self.grant is not UNSET:
            out["grant"] = None if self.grant is None else self.grant.to_json()
        out["replayed"] = self.replayed
        return out

    @classmethod
    def from_json(cls, data: Mapping[str, Any]) -> ProjectAccessChange:
        return cls(
            user_id=data["userId"],
            changed=data["changed"],
            event_seq=data.get("eventSeq", UNSET),
            grant=UNSET if "grant" not in data else None if data["grant"] is None else ProjectGrant.from_json(data["grant"]),
            replayed=data["replayed"] if "replayed" in data else False,
        )


