@dataclass(kw_only=True, slots=True)
class ProjectSummary(_Model):
    """
    Attributes:
        srid: Unit: epsg.
        updated_at: RFC 3339.
        owner_name: The owner's name ("Benimle paylaşılanlar" says whose it is); empty
            when the caller cannot see the owner (one who left the organisation).
        project_type: What kind of work it is: a label, not a claim of compliance, independent of `storage`.
        catalog_version: Counts changes of its name, description, type and tags; a catalog edit
            sends it as `expectedVersions["@catalog"]`. Decimal text.
        created_at: RFC 3339.
        creator_name: Who created it; empty when the caller cannot see them.
        area_unit: The unit its areas are given in (lengths and coordinates are metres of its coordinate system).
        favorite: One of the caller's favourites.
        archived_at: RFC 3339.
        opened_at: When the caller last opened it (RFC 3339).
        purge_after: In the trash: when the retention removes it for good (RFC 3339).
            Absent there: it was moved before the retention existed and stays until removed by hand.
        trashed_at: When it was moved to the trash (RFC 3339).
        trashed_by_name: Who moved it there, when the caller can see them.
    """
    id: str
    name: str
    srid: int
    data_revision: str
    updated_at: str
    tenant_id: str
    tenant_name: str
    tenant_kind: TenantKind | TenantKindName
    owner_name: str
    access: ProjectAccessView
    project_type: ProjectType | ProjectTypeName
    description: str
    tags: list[str]
    state: ProjectState | ProjectStateName
    catalog_version: str
    created_at: str
    creator_name: str
    area_unit: AreaUnit | AreaUnitName
    storage: ProjectStorage | ProjectStorageName
    favorite: bool
    archived_at: str | None | Unset = UNSET
    opened_at: str | None | Unset = UNSET
    purge_after: str | None | Unset = UNSET
    trashed_at: str | None | Unset = UNSET
    trashed_by_name: str | None | Unset = UNSET

    def to_json(self) -> dict[str, Any]:
        out: dict[str, Any] = {}
        out["id"] = self.id
        out["name"] = self.name
        out["srid"] = self.srid
        out["dataRevision"] = self.data_revision
        out["updatedAt"] = self.updated_at
        out["tenantId"] = self.tenant_id
        out["tenantName"] = self.tenant_name
        out["tenantKind"] = _enum_out(self.tenant_kind)
        out["ownerName"] = self.owner_name
        out["access"] = self.access.to_json()
        out["projectType"] = _enum_out(self.project_type)
        out["description"] = self.description
        out["tags"] = list(self.tags)
        out["state"] = _enum_out(self.state)
        out["catalogVersion"] = self.catalog_version
        out["createdAt"] = self.created_at
        out["creatorName"] = self.creator_name
        out["areaUnit"] = _enum_out(self.area_unit)
        out["storage"] = _enum_out(self.storage)
        out["favorite"] = self.favorite
        if self.archived_at is not UNSET:
            out["archivedAt"] = self.archived_at
        if self.opened_at is not UNSET:
            out["openedAt"] = self.opened_at
        if self.purge_after is not UNSET:
            out["purgeAfter"] = self.purge_after
        if self.trashed_at is not UNSET:
            out["trashedAt"] = self.trashed_at
        if self.trashed_by_name is not UNSET:
            out["trashedByName"] = self.trashed_by_name
        return out

    @classmethod
    def from_json(cls, data: Mapping[str, Any]) -> ProjectSummary:
        return cls(
            id=data["id"],
            name=data["name"],
            srid=data["srid"],
            data_revision=data["dataRevision"],
            updated_at=data["updatedAt"],
            tenant_id=data["tenantId"],
            tenant_name=data["tenantName"],
            tenant_kind=_enum_in(TenantKind, data["tenantKind"]),
            owner_name=data["ownerName"],
            access=ProjectAccessView.from_json(data["access"]),
            project_type=_enum_in(ProjectType, data["projectType"]),
            description=data["description"],
            tags=list(data["tags"]),
            state=_enum_in(ProjectState, data["state"]),
            catalog_version=data["catalogVersion"],
            created_at=data["createdAt"],
            creator_name=data["creatorName"],
            area_unit=_enum_in(AreaUnit, data["areaUnit"]),
            storage=_enum_in(ProjectStorage, data["storage"]),
            favorite=data["favorite"],
            archived_at=data.get("archivedAt", UNSET),
            opened_at=data.get("openedAt", UNSET),
            purge_after=data.get("purgeAfter", UNSET),
            trashed_at=data.get("trashedAt", UNSET),
            trashed_by_name=data.get("trashedByName", UNSET),
        )


